import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    root=Path.cwd().resolve()
    if not (root/'app/main.py').is_file():
        raise SystemExit('Run from tender-ai-platform-v6.2 project root')
    changes=[]
    for rel,entry in PAYLOAD.items():
        target=root/rel
        if target.is_symlink() or root not in target.resolve().parents:
            raise SystemExit('UNSAFE_PATH: '+rel)
        current=hashlib.sha256(target.read_bytes()).hexdigest() if target.exists() else None
        if current==entry['after']:continue
        if current!=entry['before']:
            raise SystemExit('SOURCE_VERSION_CONFLICT: '+rel+'; no files changed')
        if hashlib.sha256(entry['text'].encode()).hexdigest()!=entry['after']:
            raise SystemExit('PAYLOAD_CHECKSUM_FAILED: '+rel)
        compile(entry['text'],rel,'exec')
        changes.append((rel,target,entry))
    for rel in ('app/sources/gpb/adapter.py','app/sources/gpb/document_cache.py','app/sources/gpb/archives.py'):
        if not (root/rel).is_file():raise SystemExit('MISSING_GPB_DEPENDENCY: '+rel)
    print('FILES_TO_UPDATE:',len(changes),flush=True)
    if args.check:return
    if changes:
        backup=Path(tempfile.mkdtemp(prefix='gpb-keywords-backup-',dir=root.parent))
        for rel,target,entry in changes:
            if target.exists():
                saved=backup/rel;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved)
        (backup/'restore.json').write_text(json.dumps({'project':str(root),'files':[
            {'path':rel,'before':entry['before'],'after':entry['after']} for rel,target,entry in changes]},indent=2))
        print('BACKUP:',backup,flush=True)
        written=[]
        try:
            for rel,target,entry in changes:
                target.parent.mkdir(parents=True,exist_ok=True)
                fd,tmp=tempfile.mkstemp(dir=target.parent)
                try:
                    with os.fdopen(fd,'w') as f:f.write(entry['text'])
                    os.chmod(tmp,target.stat().st_mode & 0o777 if target.exists() else 0o644)
                    os.replace(tmp,target);written.append((rel,target,entry))
                finally:
                    if os.path.exists(tmp):os.unlink(tmp)
        except Exception:
            for rel,target,entry in reversed(written):
                if entry['before'] is None:target.unlink(missing_ok=True)
                else:shutil.copy2(backup/rel,target)
            raise
